canvas.style:
border: 1px solid #ccc; border-radius: 4px;
                                               width: 100%; height: 160px; cursor: crosshair;
                                               background: #fff;

t.script:
(function() {
    var canvas = document.getElementById('sig-canvas');
    var ctx = canvas.getContext('2d');
    var drawing = false;
    var hasDrawn = false;

    function resize() {
        var rect = canvas.getBoundingClientRect();
        var img = ctx.getImageData(0, 0, canvas.width, canvas.height);
        canvas.width = rect.width;
        canvas.height = 160;
        ctx.putImageData(img, 0, 0);
    }
    resize();
    window.addEventListener('resize', resize);

    function pos(e) {
        var r = canvas.getBoundingClientRect();
        var src = e.touches ? e.touches[0] : e;
        return { x: src.clientX - r.left, y: src.clientY - r.top };
    }

    canvas.addEventListener('mousedown',  function(e) { drawing = true; var p = pos(e); ctx.beginPath(); ctx.moveTo(p.x, p.y); });
    canvas.addEventListener('mousemove',  function(e) { if (!drawing) return; var p = pos(e); ctx.lineTo(p.x, p.y); ctx.stroke(); hasDrawn = true; updateBtn(); });
    canvas.addEventListener('mouseup',    function()  { drawing = false; });
    canvas.addEventListener('mouseleave', function()  { drawing = false; });
    canvas.addEventListener('touchstart', function(e) { e.preventDefault(); drawing = true; var p = pos(e); ctx.beginPath(); ctx.moveTo(p.x, p.y); });
    canvas.addEventListener('touchmove',  function(e) { e.preventDefault(); if (!drawing) return; var p = pos(e); ctx.lineTo(p.x, p.y); ctx.stroke(); hasDrawn = true; updateBtn(); });
    canvas.addEventListener('touchend',   function()  { drawing = false; });

    document.getElementById('sig-clear').addEventListener('click', function() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        hasDrawn = false;
        updateBtn();
    });

    var consent = document.getElementById('consent_check');
    consent.addEventListener('change', updateBtn);

    function updateBtn() {
        var btn = document.getElementById('sign-submit-btn');
        btn.disabled = !(hasDrawn and consent.checked);
    }

    document.getElementById('sign_form').addEventListener('submit', function() {
        document.getElementById('sig-data').value = canvas.toDataURL('image/png');
    });
})();
